m as (select d.id, v.photo, v.descr from dishes d join v on lower(trim(d.name)) = lower(trim(v.name)))
update dishes d set descr_old = coalesce(d.descr_old, d.descr), descr = m.descr,
       photo = case when coalesce(d.photo,'') = '' then m.photo else d.photo end   -- уже загруженные вами фото не заменяются
  from m where d.id = m.id;

-- проверка: каких блюд из списка нет в меню (переименованы или удалены)
